Func<dynamic, Context, CancellationToken, Task> HandleAsync = (view, ctx, ct) =>
{
    if (view.Host is not Orc.Game.Cards.UnitCard host) { return Task.CompletedTask; }
    if (view.Unit is not Orc.Game.Cards.UnitCard deployed || !object.ReferenceEquals(deployed, host))
    {
        return Task.CompletedTask; // 非本单位部署：不处理
    }

    Orc.Game.Cards.KeywordRules.ResetActionQuotas(deployed); // 置额度（重复信号幂等）
    return Task.CompletedTask;
};
